using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EngineAssaultAction", menuName = "Data/Battle/Battle Actions/Hevelius/EngineAssault Action")]
public class EngineAssaultAction : PurifyCounterBasedAction
{
	[Header("Engine Assault")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		int num = 0;
		for (int i = 0; i < currentCompanions.RuntimeCompanions.Count; i++)
		{
			num += currentCompanions.RuntimeCompanions[i].CompanionLevel + 1;
		}
		return num;
	}
}
